46	const PROCESSING_FEE = 5;
47	
48	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
49	  sword: 100,
50	  amulet: 60,
51	  staff: 80,
52	  potion: 40,
53	  rune: 25,
54	  moonstone: 25,
55	};
56	
57	const ALIKE_ITEMS_PER_BLOCK = 3;
58	const BLOCK_BASE_PREMIUM = 60;
59	const CURSE_SURCHARGE_RATE = 0.5;
60	const HIGH_ENCHANTMENT_LEVEL = 5;
61	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
62	const LOYALTY_YEARS = 2;
63	const LOYALTY_DISCOUNT_RATE = 0.2;
64	
65	const sum = (amounts: number[]): number =>
66	  amounts.reduce((total, amount) => total + amount, 0);
67	
68	const groupByType = (items: Item[]): Item[][] => {
69	  const groups = new Map<string, Item[]>();
70	
71	  for (const item of items) {
72	    const group = groups.get(item.type);
73	    if (group) group.push(item);
74	    else groups.set(item.type, [item]);
75	  }
76	
77	  return [...groups.values()];
78	};
79	
80	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type];
81	
82	const basePremiumOfGroup = (group: Item[]): number =>
83	  group.length === ALIKE_ITEMS_PER_BLOCK ? BLOCK_BASE_PREMIUM : sum(group.map(basePremiumOf));
84	
85	const curseSurchargeOf = (item: Item): number =>
86	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
87	
88	const highEnchantmentSurchargeOf = (item: Item): number =>
89	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
90	    ? basePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
91	    : 0;
92	
93	const surchargesOf = (item: Item): number =>
94	  curseSurchargeOf(item) + highEnchantmentSurchargeOf(item);
95	
96	const quote = ({ items }: QuoteStep, customer: Customer): StepResult => {
97	  const totalBasePremium = sum(groupByType(items).map(basePremiumOfGroup));
98	  const totalSurcharges = sum(items.map(surchargesOf));
99	  const loyaltyDiscount =
100	    customer.yearsWithMHPCO >= LOYALTY_YEARS ? totalBasePremium * LOYALTY_DISCOUNT_RATE : 0;
101	
102	  return {
103	    premium: totalBasePremium + totalSurcharges - loyaltyDiscount + PROCESSING_FEE,
104	  };
105	};
106	
107	export const runScenario = (scenario: Scenario): ScenarioResult => ({
108	  results: [quote(scenario.steps[0] as QuoteStep, scenario.customer)],
109	});
